@@ -2899,12 +2899,12 @@ Enigmail.msg = {

     const otherLabel = document.getElementById("otherLabel");
     if (myIdToSkipInList) {
-      document.l10n.setAttributes(otherLabel, "openpgp-other-enc-all-key-ids");
